for i,j,t in [(4,0,2),(5,3,2),(4,7,2.02),(5,72,2.02),(6,137,1.9),(6,0,2.08),(6,1,2.08),(0,1,1.24),(1,2,1.37),(2,3,1.22)]: print(i,j,np.linalg.norm(p[i]-p[j]))
