 print(start,'max internal',max(vals,key=lambda x:x[2]))
 # count potential extraneous heavy bonds inside ligand
 expected={tuple(sorted([b.GetBeginAtomIdx(),b.GetEndAtomIdx()])) for b in m.GetBonds()}
 for i in range(29):
  for j in range(i):
   if (j,i) not in expected and np.linalg.norm(p[start+i]-p[start+j])<1.75: print('EXTRA BOND',start+i,start+j)
